{
  "name": "builder_all_pairs_margin_rank_blend_clamp_eps_guard_002",
  "intuition": "Preserves margin_rank_blend weighting with added clamp and epsilon guards for numerical stability, avoiding tie-zone filtering and preserving pair topology without normalization.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
