  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    low = float(extra.get('band_low', 0.5))\n    high = float(extra.get('band_high', 2.0))\n    def sigmoid(x):\n        return 1.0 / (1.0 + (-x).exp())\n    w_low = sigmoid(gap - low)\n    w_high = sigmoid(high - gap)\n    raw = w_low * w_high * gap.clamp_min(0.0)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0)\n    weight = raw.clamp(0.25, 4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_combined', 'weight_family': 'gap_bandpass_smooth_combined'})"
}

{
  "name": "reweight_pairwise_margin_rank_gap_linear_smooth_clamp_001",
  "intuition": "Smoothly blend margin rank sigmoid and gap linear signals with softened clamp to improve weight stability while preserving pairwise all_pairs topology and no normalization.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "margin_rank_gap_linear",
    "constraint_family": "clamp_only"
