  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'reweight_pairwise_margin_rank_gap_linear_smooth_clamp_001', 'weight_family': 'margin_rank_gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Smooth clamp function: soft clipping with sigmoid-based smooth min/max\n    def smooth_clamp(x, min_val, max_val, softness=10.0):\n        x_min = min_val + (x - min_val) / (1 + torch.exp(-softness * (x - min_val)))\n        x_max = max_val - (max_val - x_min) / (1 + torch.exp(-softness * (max_val - x_min)))\n        return x_max\n    rank = feature_cache.get('rank', torch.zeros_like(objective))\n    beta_rank = float(extra.get('beta_rank', 4.0))\n    sigmoid_signal = torch.sigmoid(beta_rank * (rank[b_idx, loser_idx] - rank[b_idx, winner_idx]))\n    gap_nonneg = torch.clamp(gap, min=0.0)\n    gap_weight = smooth_clamp(gap_nonneg, 0.25, 4.0, softness=8.0)\n    combined_weight = sigmoid_signal * gap_weight\n    combined_weight = torch.nan_to_num(combined_weight, nan=0.0, posinf=0.0, neginf=0.0).clamp(min=0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=combined_weight, meta={'builder': 'reweight_pairwise_margin_rank_gap_linear_smooth_clamp_001', 'weight_family': 'margin_rank_gap_linear'})"
}

