{
  "name": "all_pairs_gap_log_blend",
  "intuition": "Blend logarithmically scaled objective gap with normalized rank difference to emphasize moderate and diverse gaps while preserving all-pairs topology and uncapped weights",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_log_rank_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
