    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_log_blend', 'geometry_family': 'dense_all_pairs', 'cap_family': 'uncapped_full', 'weight_family': 'gap_log_rank_blend', 'constraint_family': 'clamp_only'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = torch.clamp(gap, min=0.0)\n    # log scale the gap with stability\n    eps = 1e-6\n    log_gap = torch.log1p(gap + eps)\n    max_log_gap_per_instance = torch.clamp(torch.amax(log_gap.view(-1), dim=0), min=eps)\n    norm_log_gap = log_gap / (max_log_gap_per_instance + eps)\n    rank_diff = torch.abs(rank[b_idx, loser_idx] - rank[b_idx, winner_idx])\n    rank_max = torch.clamp(torch.amax(rank, dim=1) - torch.amin(rank, dim=1), min=1.0)[b_idx]\n    norm_rank_diff = rank_diff / rank_max\n    beta = float(extra.get('beta', 0.6))\n    raw_weight = beta * norm_log_gap + (1.0 - beta) * norm_rank_diff\n    raw_weight = torch.nan_to_num(raw_weight, nan=0.0, posinf=0.0, neginf=0.0)\n    clamp_lo = float(extra.get('clamp_lo', 0.25))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    weight = torch.clamp(raw_weight, min=clamp_lo, max=clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_log_blend', 'geometry_family': 'dense_all_pairs', 'cap_family': 'uncapped_full', 'weight_family': 'gap_log_rank_blend', 'constraint_family': 'clamp_only'})"
